python
def branchNotebookProofStrip(root, k):
    a=root
    out=[]
    def visit(node):
        if not node: return
        out.append(node.val)
        visit(node.left)
        visit(node.right)
    visit(a)
    return out


java
class Solution {
  public int[] branchNotebookProofStrip(TreeNode root, int k) {
    TreeNode a=root; List<Integer> out=new ArrayList<>();
    {class Walk {void visit(TreeNode node){if(node==null)return;out.add(node.val);visit(node.left);visit(node.right);}}new Walk().visit(a);}
    return out.stream().mapToInt(Integer::intValue).toArray();
  }
}
